local ParquetFloorMaker = {}
local PRODUCTS = {
    simple_oak_parquet = { name = "Preprost hrastov parket", woodCost = 3, time = 5, cost = 80, beauty = 22, happiness = 1, description = "Preprost hrastov parket za hišo." },
    herringbone_parquet = { name = "Ribja kost parket", woodCost = 4, time = 7, cost = 220, beauty = 38, happiness = 2, prestige = 2, description = "Ribja kost parket za trgovce." },
    walnut_inlaid_parquet = { name = "Orehov vloženi parket", woodCost = 4, leatherCost = 1, time = 10, cost = 540, beauty = 52, happiness = 2, prestige = 6, description = "Orehov vloženi parket za plemiče." },
    silver_trimmed_parquet = { name = "Srebrnoobrobljeni parket", woodCost = 4, silverCost = 1, leatherCost = 1, time = 14, cost = 1300, beauty = 65, happiness = 3, prestige = 14, description = "Srebrnoobrobljeni parket za visoke plemiče." },
    gold_inlaid_parquet = { name = "Zlatovloženi parket", woodCost = 5, goldCost = 1, silverCost = 1, leatherCost = 1, jewelCost = 1, time = 18, cost = 2800, beauty = 78, happiness = 5, prestige = 27, description = "Zlatovloženi parket z draguljem za visoko plemstvo." },
    royal_grand_parquet = { name = "Kraljevski veliki parket", woodCost = 7, goldCost = 2, silverCost = 2, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 25, cost = 6000, beauty = 92, happiness = 12, prestige = 58, description = "Veliki kraljevski parket z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    parquet_workshop = { name = "Parketna delavnica", cost = { gold = 260, wood = 160, stone = 100 }, upkeep = 6, qualityBonus = 5 },
    flooring_loft = { name = "Talna podstrešje", cost = { gold = 950, wood = 320, stone = 240, silver = 6 }, upkeep = 22, qualityBonus = 18 },
    master_floor_atelier = { name = "Mojstrski talni atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_parquet_palace = { name = "Kraljevska parketna palača", cost = { gold = 11500, wood = 600, stone = 800, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
ParquetFloorMaker.woodStock = 20; ParquetFloorMaker.leatherStock = 8; ParquetFloorMaker.silverStock = 6; ParquetFloorMaker.goldStock = 6; ParquetFloorMaker.jewelStock = 4; ParquetFloorMaker.pearlStock = 4
ParquetFloorMaker.productStock = {}; ParquetFloorMaker.buildings = {}; ParquetFloorMaker.maker = nil; ParquetFloorMaker.activeMaking = {}; ParquetFloorMaker.totalProducts = 0; ParquetFloorMaker.dayTimer = 0
function ParquetFloorMaker.init() ParquetFloorMaker.woodStock=20; ParquetFloorMaker.leatherStock=8; ParquetFloorMaker.silverStock=6; ParquetFloorMaker.goldStock=6; ParquetFloorMaker.jewelStock=4; ParquetFloorMaker.pearlStock=4; ParquetFloorMaker.productStock={}; ParquetFloorMaker.buildings={}; ParquetFloorMaker.maker=nil; ParquetFloorMaker.activeMaking={}; ParquetFloorMaker.totalProducts=0; ParquetFloorMaker.dayTimer=0; print("[ParquetFloorMaker] Royal Parquet Floor Maker System initialized (6 products, 4 buildings)") end
function ParquetFloorMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ParquetFloorMaker.maker={name=n or ("Parketar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Parketar najet: %s (spretnost: %d)",ParquetFloorMaker.maker.name,s),"success") end; return true end
function ParquetFloorMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ParquetFloorMaker.build(id) local ok,e=ParquetFloorMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ParquetFloorMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ParquetFloorMaker.getQualityBonus() local b=0; for _,bd in ipairs(ParquetFloorMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ParquetFloorMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and ParquetFloorMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ParquetFloorMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ParquetFloorMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ParquetFloorMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ParquetFloorMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ParquetFloorMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ParquetFloorMaker.buildings==0 then return false,"Potrebna parketna delavnica" end; if not ParquetFloorMaker.maker then return false,"Potreben parketar" end; return true end
function ParquetFloorMaker.make(pt,qty) qty=qty or 1; local ok,e=ParquetFloorMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then ParquetFloorMaker.woodStock=ParquetFloorMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ParquetFloorMaker.leatherStock=ParquetFloorMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ParquetFloorMaker.silverStock=ParquetFloorMaker.silverStock-d.silverCost*qty end; if d.goldCost then ParquetFloorMaker.goldStock=ParquetFloorMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ParquetFloorMaker.jewelStock=ParquetFloorMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ParquetFloorMaker.pearlStock=ParquetFloorMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ParquetFloorMaker.maker then t=math.max(1,t-math.floor(ParquetFloorMaker.maker.skill/12)) end; table.insert(ParquetFloorMaker.activeMaking,{id="parquet_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Polaganje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ParquetFloorMaker.completeMaking(m) local q=1.0+(ParquetFloorMaker.getQualityBonus()/100); if ParquetFloorMaker.maker then q=q+(ParquetFloorMaker.maker.skill/140) end; q=math.min(2.5,q); ParquetFloorMaker.productStock[m.productType]=(ParquetFloorMaker.productStock[m.productType] or 0)+m.quantity; ParquetFloorMaker.totalProducts=ParquetFloorMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ParquetFloorMaker.maker then ParquetFloorMaker.maker.itemsMade=ParquetFloorMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ParquetFloorMaker.maker.skill=math.min(100,ParquetFloorMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Parket položen: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"parquet.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function ParquetFloorMaker.update(dt) if not _G.state then return end; ParquetFloorMaker.dayTimer=ParquetFloorMaker.dayTimer+dt; if ParquetFloorMaker.dayTimer>=30 then ParquetFloorMaker.dayTimer=0; for i=#ParquetFloorMaker.activeMaking,1,-1 do local m=ParquetFloorMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ParquetFloorMaker.completeMaking(m); table.remove(ParquetFloorMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ParquetFloorMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ParquetFloorMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ParquetFloorMaker.getStats() return {woodStock=ParquetFloorMaker.woodStock,leatherStock=ParquetFloorMaker.leatherStock,silverStock=ParquetFloorMaker.silverStock,goldStock=ParquetFloorMaker.goldStock,jewelStock=ParquetFloorMaker.jewelStock,pearlStock=ParquetFloorMaker.pearlStock,productStock=ParquetFloorMaker.productStock,numBuildings=#ParquetFloorMaker.buildings,hasMaker=ParquetFloorMaker.maker~=nil,makerName=ParquetFloorMaker.maker and ParquetFloorMaker.maker.name or "—",makerSkill=ParquetFloorMaker.maker and ParquetFloorMaker.maker.skill or 0,activeMaking=#ParquetFloorMaker.activeMaking,totalProducts=ParquetFloorMaker.totalProducts} end
return ParquetFloorMaker
